entries[114842] = { ["name"] = "Buch der Fluggestalt", ["text"] = "Ashran\nWird beim Aufheben gebunden\nEinzigartig (5)\nKlassen: Druide\nBenutzen: Ermöglicht die Verwendung der Fluggestalt in Ashran. Hält 1 Stunde lang an. Kann nur in Ashran verwendet werden." }
entries[114843] = { ["name"] = "Handbuch: Taschendiebstahl", ["text"] = "Ashran\nWird beim Aufheben gebunden\nEinzigartig (5)\nKlassen: Schurke\nBenutzen: Ermöglicht es, Eure Fähigkeit 'Taschendiebstahl' auf gegnerische Spielercharaktere anzuwenden und ihnen bis zu 5 Artefaktfragmente zu stehlen. Dabei unterliegt die Fähigkeit aber einer Abklingzeit von 10 Sek. Funktioniert nur in Ashran." }
entries[114844] = { ["name"] = "Schriftrolle der Berührung des Verhängnisses", ["text"] = "Ashran\nWird beim Aufheben gebunden\nEinzigartig (5)\nKlassen: Mönch\nBenutzen: Lehrt den Mönch 'Berührung des Verhängnisses'.\n\n'Berührung des Verhängnisses' tötet Spielercharaktere mit weniger als 20% Gesundheit oder Kreaturen unter Stufe 50 sofort. Funktioniert nur in Ashran." }
entries[114845] = { ["name"] = "Foliant des Blinzelns", ["text"] = "Ashran\nWird beim Aufheben gebunden\nEinzigartig (5)\nKlassen: Magier\nBenutzen: Halbiert die Abklingzeit von 'Blinzeln'. Funktioniert nur in Ashran." }
entries[114846] = { ["name"] = "Siegel des Todesgriffs", ["text"] = "Ashran\nWird beim Aufheben gebunden\nEinzigartig (5)\nKlassen: Todesritter\nBenutzen: Euer 'Todesgriff' verfügt über 1 zusätzliche Aufladung. Kann nur in Ashran verwendet werden." }
entries[114847] = { ["name"] = "Schrifttafel des Geisterwolfs", ["text"] = "Ashran\nWird beim Aufheben gebunden\nEinzigartig (5)\nKlassen: Schamane\nBenutzen: Erhöht sogar im Kampf die Bewegungsgeschwindigkeit in Geisterwolfgestalt auf die von epischen Reittieren und macht Euch nach 5 Sek. in Geisterwolfgestalt unsichtbar. Funktioniert nur in Ashran." }
entries[114848] = { ["name"] = "Zauberfoliant der dämonischen Wandlung", ["text"] = "Ashran\nWird beim Aufheben gebunden\nEinzigartig (5)\nKlassen: Hexenmeister\nBenutzen: Euer Zauber 'Dämonensklave' wird jetzt zu 'Dämonische Wandlung'. Funktioniert nur in Ashran.\n\nDämonische Wandlung\nWandelt die Seele des Ziels in die eines Dämons um und stellt es daraufhin unter Euren Befehl. Das Ziel kann kein Spielercharakter sein. Hält bis zu 5 Min. lang an.\n\nKann nur auf Ziele bis Stufe 60 in Ashran gewirkt werden." }
