entries[114851] = { ["name"] = "Muster: Hexenzwirnstoff", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung von Hexenzwirnstoff.\nProduziert 8 (plus zusätzliche, je nach Schneiderfertigkeit).\n\nKann auch magisches Wasser und/oder magische Luft erzeugen.\n\nDie Abklingzeit wird täglich abgeschlossen.\nBenötigt Schneiderei (1)\nVerkaufspreis:\nHexenzwirnstoff\nWird beim Aufheben gebunden\nHandwerksmaterial\n\"Zu feinem Stoff gewebtes Fell, das als Grundlage für die meisten Schneidereiprodukte in Draenor dient.\"\nVerkaufspreis:\nBenötigt Prächtiges Fell (20), Gorgrondfliegenfalle (10)" }
