entries[114984] = { ["name"] = "Geheimnisvoller Ranzen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nBenötigt Klassische Inschriftenkunde (1)\n\"Pulsiert mit einer schwachen magischen Aura.\"" }
entries[114986] = { ["name"] = "Giftige Umbrafennkräuter", ["text"] = "Questgegenstand\nEinzigartig\n\"Vorsicht – explosiv.\"" }
entries[114987] = { ["name"] = "Fläschchen giftige Tinte", ["text"] = "Questgegenstand\nEinzigartig\n\"Wunderschön, aber tödlich.\"" }
entries[114988] = { ["name"] = "Von Geisterhand berührte Materialien", ["text"] = "Questgegenstand\nEinzigartig\n\"Waruk hat die Gegenstände mit einem Teil seiner Essenz durchwirken lassen.\"" }
entries[114989] = { ["name"] = "Toxinresistenter Ranzen", ["text"] = "Questgegenstand\nEinzigartig\n\"Vorsichtig behandeln!\"" }
entries[114990] = { ["name"] = "Oru'kais Szepter", ["text"] = "Questgegenstand\n\"Ein eisiger Hauch geht von dem Inneren des Szeptersteins aus.\"" }
entries[114996] = { ["name"] = "Blutstein", ["text"] = "Questgegenstand\n\"Wird an potenzielle Gladiatoren für den Kampf des Blutchampions überreicht.\"" }
entries[114999] = { ["name"] = "Prächtiges Fell", ["text"] = "Handwerksmaterial\n\"Fell von Wildtieren Draenors. Zutat für Stoffe.\"" }
entries[115002] = { ["name"] = "Rohes Tierleder", ["text"] = "Handwerksmaterial\n\"Wird von Spielercharakteren gesammelt, die den Beruf Kürschnerei ausüben. Kann im Auktionshaus verkauft und erworben werden.\"" }
entries[115005] = { ["name"] = "Wildes Festmahl", ["text"] = "\"Eine herzhafte und sättigende Mahlzeit für eine ganze Gruppe.\"" }
entries[115008] = { ["name"] = "Verzauberte Hochfelsarmschienen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nBenötigt Klassische Verzauberkunst (1)\n\"Eine mächtige Verzauberung entströmt diesen Armschienen, aber wie sie bewerkstelligt wurde, übersteigt Eure Fähigkeiten.\"" }
entries[115009] = { ["name"] = "Verbesserte Eisenfalle", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Platziert eine Eisenfalle, die ein ausgewachsenes verwundetes Tier fangen kann. Bleibt 1 Min. lang bestehen.\n\nProduzierte Materialien:\nGrollhuf, Elekk: Leder\nTalbuk, Wolf: Fell\nFlussbestie, Eber: Fleisch\n\nFunktioniert nicht bei sehr mächtigen Wildtieren. (5 Sek. Abklingzeit)" }
entries[115010] = { ["name"] = "Tödliche Eisenfalle", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Platziert eine Eisenfalle, die ein ausgewachsenes verwundetes Tier fangen kann. Bleibt 1 Min. lang bestehen.\n\nProduzierte Materialien:\nGrollhuf, Elekk: Leder\nTalbuk, Wolf: Fell\nFlussbestie, Eber: Fleisch (5 Sek. Abklingzeit)" }
entries[115011] = { ["name"] = "Oru'kais Glutring", ["text"] = "Questgegenstand\nBenutzen: Hebt die Frostverzauberung auf.\n\"Der Ring versengt den Träger langsam, die Hitze kann jedoch auf ein Ziel kanalisiert werden.\"" }
entries[115012] = { ["name"] = "Zerschmetterter Stein", ["text"] = "\"Wir haben die Insel der Felsklauen wochenlang durchkämmt und fanden... das!\"\nVerkaufspreis:" }
entries[115013] = { ["name"] = "Zeremonielle Roben des Schattenmonds", ["text"] = "Questgegenstand" }
entries[115018] = { ["name"] = "Geflickter Stoff des Schattenmonds", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Beginnt mit Ameekas Ritual im gebündelten Mondlicht.\n\"Die Fetzen wurden fein säuberlich zu einem großen Stoffquadrat zusammengenäht.\"" }
entries[115019] = { ["name"] = "Magieerfüllter Stoff des Schattenmonds", ["text"] = "Questgegenstand\nEinzigartig\n\"Die Fasern dieses Stoffes wurden mit Magie durchwirkt, um ihn widerstandsfähiger zu machen.\"" }
