entries[115272] = { ["name"] = "Forschungsaufzeichnungen", ["text"] = "Questgegenstand\n\"Die wissenschaftlichen Ausführungen eines wahren Genies oder das wertlose Gefasel eines durch und durch kranken Verstandes. Schwer zu sagen, welches von beidem...\"" }
entries[115273] = { ["name"] = "Das Auge von Anzu", ["text"] = "Questgegenstand\n\"Ein Zauberfokus aus Terokks dunkleren Tagen.\"" }
entries[115274] = { ["name"] = "Antifungusstiefel", ["text"] = "Questgegenstand\n\"Manche wollen topmodische Schuhe, andere bevorzugen Stiefel mit magischen Kräften. Wieder andere sind schon zufrieden, wenn ihre Stiefel keinen Käsegeruch verströmen.\"" }
entries[115275] = { ["name"] = "Expeditionsvorräte", ["text"] = "Questgegenstand\n\"Ein standardmäßiges Nesingwary-Versorgungspaket, gefüllt mit Kugeln und Bier... aber größtenteils Kugeln.\"" }
entries[115276] = { ["name"] = "Pilzsporen", ["text"] = "Questgegenstand\n\"Der Zangarpilzstamm ist sehr anpassungsfähig und kommt laut aktuellem Forschungsstand nur in Draenor vor.\"" }
entries[115277] = { ["name"] = "Fungusgehirn", ["text"] = "Questgegenstand\n\"Eine weiche, schwammartige Fungusmasse, die die zentrale Kontrolle über den Körper eines Sporenriesen ausübt.\"" }
entries[115278] = { ["name"] = "Gnomischer Standorttransponder", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nBenötigt Klassische Ingenieurskunst (1)\n\"Funktioniert in 60 Prozent der Fälle jedes Mal!\"" }
entries[115279] = { ["name"] = "Stibitzte Teile", ["text"] = "Questgegenstand\n\"Ehemaliges Eigentum der Eisernen Horde.\"" }
entries[115280] = { ["name"] = "Dominanzstein", ["text"] = "Wird beim Aufheben gebunden\n\"Ein hässlicher und seltsam geformter Edelstein, der dennoch vor restlicher magischer Energie vibriert.\"" }
entries[115281] = { ["name"] = "Verzauberte Hochfelsarmschienen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nBenötigt Klassische Verzauberkunst (1)\n\"Eine mächtige Verzauberung entströmt diesen Armschienen, aber wie sie bewerkstelligt wurde, übersteigt Eure Fähigkeiten.\"" }
entries[115282] = { ["name"] = "Mikroverteidiger der Draenei", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\n80 ( 80)" }
entries[115287] = { ["name"] = "Filigraner karminroter Anhänger", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nBenötigt Klassische Juwelierskunst\n(1)\n\"Fühlt sich warm an.\"" }
entries[115288] = { ["name"] = "Foliant des Teufelsbrechers", ["text"] = "Questgegenstand\nEinzigartig\n\"Die Seiten sind leer. Absolut leer! Vielleicht kann Khadgar mehr herausfinden.\"" }
entries[115289] = { ["name"] = "Siegel des Zaubererkönigs", ["text"] = "Questgegenstand\nEinzigartig\n\"Ein faustgroßer Ring, in den Mar'goks persönliches Siegel eingraviert ist und der vor magischer Energie brummt.\"" }
entries[115290] = { ["name"] = "Oru'kais Stab", ["text"] = "Questgegenstand\n\"In der Nähe dieses Stabes scheint die Zeit langsamer zu vergehen.\"" }
entries[115291] = { ["name"] = "Elekkschmorbraten", ["text"] = "Benutzen: Sättigt bis zu 25 Leute in Eurem Schlachtzug oder Eurer Gruppe mit einem Festmahl des Blutes.\n\nStellt im Verlauf von 20 Sek. 8173 Gesundheit und ( 2125 / 5 * 20) Mana wieder her. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und Euer höchster Sekundärwert wird 1 Stunde lang um 6 erhöht.\nVerkaufspreis:" }
