entries[115499] = { ["name"] = "Persönlicher Raketenkurier", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Bringt die Artefaktmarken zur Basis Eurer Fraktion zurück. (30 Min Abklingzeit)" }
entries[115500] = { ["name"] = "Einwegtaschenflugmaschine", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenötigt eine Horde-Rasse\nBenutzen: Beschwört eine Taschenflugmaschine, die Eure Artefaktfragmente zurück zum Vorposten des Kriegsspeers bringt, wofür Ihr entsprechend Ehre und Ruf erhaltet.\n\nEure Artefaktfragmente werden gleichmäßig auf die verfügbaren Ziele der Horde verteilt. (2 Std. Abklingzeit)\n5 Aufladungen\nBenötigt Vol'jins Speer\n- Freundlich\nVerkaufspreis:" }
entries[115501] = { ["name"] = "Kowalskis Spieluhr", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Stößt besänftigende Klänge in Richtung aller gegnerischen Kreaturen innerhalb von 30 Metern aus, sodass die Reichweite, in der sie Gegner wahrnehmen, verringert wird. Die Spieluhr hält 1 Stunde lang an, bevor sie erneut aufgezogen werden muss. (15 Min Abklingzeit)\n\"Bei den Barden von Azeroth sehr begehrt.\"" }
entries[115502] = { ["name"] = "Kleiner glitzernder Splitter", ["text"] = "Benutzen: Fügt 10 kleine glitzernde Splitter zu einem glitzernden Splitter zusammen.\nHandwerksmaterial" }
entries[115503] = { ["name"] = "Lodernder Diamantenanhänger", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Bedeckt Eure Füße mit glühend heißem Magma.\n\nNur in Draenor verwendbar. (30 Min Abklingzeit)\n\"Tausendmal ist nichts passiert.\"\nVerkaufspreis:" }
entries[115504] = { ["name"] = "Zerbrochener temporaler Kristall", ["text"] = "Benutzen: Fügt 10 zerbrochene temporale Kristalle zu einem temporalen Kristall zusammen.\nHandwerksmaterial" }
entries[115505] = { ["name"] = "LeBlancs Blockflöte", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Spielt eine anziehende Melodie, die die örtliche Fauna herbeiruft, um Euch im Kampf gegen andere Spielercharaktere innerhalb von 60 Metern beizustehen. (1 Stunde Abklingzeit)\nBenötigt Vol'jins Speer\n- Respektvoll\n\"Bei den Barden von Azeroth sehr begehrt.\"" }
entries[115506] = { ["name"] = "Verkleidung eines Astsassinen", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Verkleidet den Träger als Baum und entfernt ihn aus dem Kampf. Kann nur in der Wildnis von Draenor verwendet werden. (10 Min Abklingzeit)\n\"Wird von Baumassassinen zum ermorden hochrangiger Bäume verwendet. Ernsthaft.\"" }
entries[115507] = { ["name"] = "Erschöpftes Kristallfragment", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nBenötigt Klassische Juwelierskunst\n(1)\n\"Seine Energie lässt nach, noch während Ihr es in der Hand haltet.\"" }
entries[115508] = { ["name"] = "Draenischer Stein", ["text"] = "Wird beim Aufheben gebunden\nHandwerksmaterial\nVerkaufspreis:" }
entries[115509] = { ["name"] = "Elementartafel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (3)\n\"Eine Steintafel mit uralten Elementarglyphen aus der turbulenten Vergangenheit von Draenor.\"" }
entries[115510] = { ["name"] = "Elementarrune", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Fügt 300 Elementarrunen zu einer Elementartafel zusammen.\n\"Ein Fragment einer seit langer Zeit verschollenen Tafel. Bereits das Fragment besitzt Macht über Feuer- und Steinkreaturen.\"" }
entries[115511] = { ["name"] = "Bizmos große Badabumm-Bombe", ["text"] = "Benutzen: Fügt Feinden 6 Frostschaden zu und friert sie 5 Sek. lang fest. Verursachter Schaden kann den Effekt unterbrechen. (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[115512] = { ["name"] = "Gazlowes Gargantuagranate", ["text"] = "Benutzen: Fügt Feinden 6 Frostschaden zu und friert sie 5 Sek. lang fest. Verursachter Schaden kann den Effekt unterbrechen. (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[115513] = { ["name"] = "Schlachtstandarte von Wrynns Vorhut", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Platziert eine Schlachtstandarte mit 300000 Gesundheit, die die Vielseitigkeit aller Gruppenmitglieder, die sich im Umkreis von 45 Metern der Schlachtstandarte befinden, um 272 erhöht. Hält bis Abbruch lang an. Kann nur in Ashran benutzt werden. (15 Min Abklingzeit)\nBenötigt Wrynns Vorhut\n- Freundlich" }
entries[115514] = { ["name"] = "Schlachtstandarte von Vol'jins Speer", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Platziert eine Schlachtstandarte mit 300000 Gesundheit an Eurem Standort. In Ashran erhöht die Schlachtstandarte die Vielseitigkeit aller Gruppenmitglieder im Umkreis von 45 Metern um 272 . Hält bis Abbruch lang an. (15 Min Abklingzeit)\nBenötigt Vol'jins Speer\n- Freundlich" }
entries[115516] = { ["name"] = "Energieerfüllter Kristall", ["text"] = "Questgegenstand\nEinzigartig\n\"Energie wirbelt im Inneren.\"" }
entries[115517] = { ["name"] = "Wappenrock von Wrynns Vorhut", ["text"] = "Wird beim Aufheben gebunden\nWappenrock\nBenötigt Wrynns Vorhut\n- Ehrfürchtig" }
entries[115518] = { ["name"] = "Wappenrock von Vol'jins Speer", ["text"] = "Wird beim Aufheben gebunden\nWappenrock\nBenötigt Vol'jins Speer\n- Ehrfürchtig" }
entries[115519] = { ["name"] = "Fläschchen der Ehrengebundenen", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Erhöht die durch Ziele und Siege auf Schlachtfeldern erhaltene Ehre 1 Stunde lang um 20%. Dieser Effekt bleibt über den Tod hinaus bestehen. (5 Sek. Abklingzeit)" }
entries[115520] = { ["name"] = "Verdorbenes Fläschchen der Eroberung", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig (5)\nVerkaufspreis:" }
entries[115521] = { ["name"] = "Anpassungsabzeichen des wilden Kämpfers", ["text"] = "Saison 1 von Warlords\nWird beim Aufheben gebunden\nSchmuck\nErhöht Eure Meisterschaftswertung um + 7.\nBenötigt eine Allianz-Rasse\nBenutzen: Erhöht die Vielseitigkeit 20 Sek. lang um 20 . (1 Min Abklingzeit)\nBenötigt Wrynns Vorhut\n- Freundlich\nVerkaufspreis:" }
entries[115522] = { ["name"] = "Flinke Reitgerte", ["text"] = "Ashran\nWird beim Aufheben gebunden\nEinzigartig (10)\nBenutzen: Ermöglicht es Euch, 1 Stunde lang sofort aufzusitzen, während Ihr Euch in Ashran befindet.\nBenötigt Wrynns Vorhut\n- Wohlwollend\nVerkaufspreis:" }
entries[115523] = { ["name"] = "Schwarzfausts abgetrennter Arm", ["text"] = "Questgegenstand\nEinzigartig\n\"Ist das Fleisch... oder Stein?\"" }
entries[115524] = { ["name"] = "Taladitkristall", ["text"] = "Wird beim Aufheben gebunden\nHandwerksmaterial\n\"Ein vielseitiger, im Labor erschaffener Edelstein, der in vielen Juwelierskunstvorlagen Draenors Verwendung findet.\"" }
entries[115525] = { ["name"] = "Unheimliches Ogergesicht", ["text"] = "Einzigartig\nBenutzen: Ihr nehmt 10 Min. lang die Gestalt eines Gruselogers an. (Procchance: 10%, 30s Abklingzeit) (50 Min Abklingzeit)\n5 Aufladungen" }
entries[115526] = { ["name"] = "Taladitrekristallisierer", ["text"] = "Verkaufspreis:" }
entries[115527] = { ["name"] = "Instabiler Taladitverstärker", ["text"] = "\"Der Verstärker ist instabil geworden.\"" }
entries[115529] = { ["name"] = "Instabiler großer Taladitverstärker", ["text"] = "\"Der Verstärker ist instabil geworden.\"" }
entries[115530] = { ["name"] = "Zielmarkierer N.U.K.U.L.A.R.", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 1 tag (Realzeit)\nBenutzen: Markiert einen Zielort und lässt dort nach 10 Sek. einen mächtigen Sprengkopf einschlagen, der allen Gegnern innerhalb von 20 Metern 76892 Feuerschaden zufügt. (1 Stunde Abklingzeit)\n2 Aufladungen\n\"Steht ganz offensichtlich für etwas höchst Technisches.\"" }
entries[115531] = { ["name"] = "Wirbelnder Ashranheiltrank", ["text"] = "Ashran\nBenutzen: Dieser Trank ist unzweifelhaft stark – sowohl von der Wirkung als auch im Geruch... (2 Min Abklingzeit)" }
entries[115532] = { ["name"] = "Klapprige Röntgenbrille", ["text"] = "Ashran\nWird beim Aufheben gebunden\nBenutzen: Ermöglicht es, in die Beutetaschen gegnerischer Spielercharaktere zu blicken, um diejenigen auszumachen, die Artefaktfragmente bei sich tragen. Hält 1 Stunde lang an.\nBenötigt Wrynns Vorhut\n- Wohlwollend" }
entries[115533] = { ["name"] = "Phiole mit veredeltem Serum", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Wendet das Serum auf geschwächte infizierte Goblins am Quetschpfeifenkap an. (5 Sek. Abklingzeit)" }
entries[115534] = { ["name"] = "Pennys Leuchtpistole", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Feuert ein Leuchtfeuer ab. (2 Min Abklingzeit)\n\"Dieser Auslöser wurde modifiziert, um leichter zu feuern.\"" }
entries[115535] = { ["name"] = "Ogerschädelverstärkte Schienbeinschützer", ["text"] = "Wird beim Aufheben gebunden\nBeine Platte\n15 Rüstung\n+5 [Stärke oder Intelligenz]\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 5.\nErhöht Eure Meisterschaftswertung um + 5.\nHaltbarkeit 120 / 120\nKlassen: Todesritter\nOgerschädelverstärkte Schlachtrüstung (0/5)\nOgerschädelverstärkte Schienbeinschützer\nOgerschädelverstärkte Schulterstücke\nOgerschädelverstärkte Brustplatte\nOgerschädelverstärkte Stulpen\nOgerschädelverstärkter Großhelm\nAltes Set: Bonus ist nicht aktiv\n(2) Set Blut: 'Todesstoß' verringert die Abklingzeit von 'Vampirblut' um 1 Sek.\n(2) Set Frost: Aktivierung von 'Säule des Frosts' erzeugt 30 Runenmacht.\n(2) Set Unheilig: Euer Diener verursacht 120% mehr Schaden, während 'Dunkle Transformation' aktiv ist.\n(4) Set Blut: Während 'Vampirblut' aktiv ist, kann Euer Blutschild nicht auf weniger als 3% Euer maximalen Gesundheit reduziert werden.\n(4) Set Frost: Während 'Säule des Frosts' aktiv ist, schließen Eure Spezialangriffe eine Seele in Eure Runenwaffe ein. Wenn 'Säule des Frosts' ausläuft, entlädt Eure Runenwaffe die Seelen auf Euer aktuelles Ziel und verursacht (3.51% der Angriffskraft)% Schaden pro Seele.\n(4) Set Unheilig: Wenn Ihr 'Dunkle Transformation' aktiviert, werden 1 Eurer Runen automatisch erneuert.\nVerkaufspreis:" }
entries[115536] = { ["name"] = "Ogerschädelverstärkte Schulterstücke", ["text"] = "Wird beim Aufheben gebunden\nSchulter Platte\n12 Rüstung\n+3 [Stärke oder Intelligenz]\n+5 Ausdauer\nErhöht Eure Tempowertung um + 4.\nErhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 100 / 100\nKlassen: Todesritter\nOgerschädelverstärkte Schlachtrüstung (0/5)\nOgerschädelverstärkte Schienbeinschützer\nOgerschädelverstärkte Schulterstücke\nOgerschädelverstärkte Brustplatte\nOgerschädelverstärkte Stulpen\nOgerschädelverstärkter Großhelm\nAltes Set: Bonus ist nicht aktiv\n(2) Set Blut: 'Todesstoß' verringert die Abklingzeit von 'Vampirblut' um 1 Sek.\n(2) Set Frost: Aktivierung von 'Säule des Frosts' erzeugt 30 Runenmacht.\n(2) Set Unheilig: Euer Diener verursacht 120% mehr Schaden, während 'Dunkle Transformation' aktiv ist.\n(4) Set Blut: Während 'Vampirblut' aktiv ist, kann Euer Blutschild nicht auf weniger als 3% Euer maximalen Gesundheit reduziert werden.\n(4) Set Frost: Während 'Säule des Frosts' aktiv ist, schließen Eure Spezialangriffe eine Seele in Eure Runenwaffe ein. Wenn 'Säule des Frosts' ausläuft, entlädt Eure Runenwaffe die Seelen auf Euer aktuelles Ziel und verursacht (3.51% der Angriffskraft)% Schaden pro Seele.\n(4) Set Unheilig: Wenn Ihr 'Dunkle Transformation' aktiviert, werden 1 Eurer Runen automatisch erneuert.\nVerkaufspreis:" }
entries[115537] = { ["name"] = "Ogerschädelverstärkte Brustplatte", ["text"] = "Wird beim Aufheben gebunden\nBrust Platte\n17 Rüstung\n+5 [Stärke oder Intelligenz]\n+7 Ausdauer\nErhöht Eure Tempowertung um + 4.\nErhöht Eure Meisterschaftswertung um + 5.\nHaltbarkeit 165 / 165\nKlassen: Todesritter\nOgerschädelverstärkte Schlachtrüstung (0/5)\nOgerschädelverstärkte Schienbeinschützer\nOgerschädelverstärkte Schulterstücke\nOgerschädelverstärkte Brustplatte\nOgerschädelverstärkte Stulpen\nOgerschädelverstärkter Großhelm\nAltes Set: Bonus ist nicht aktiv\n(2) Set Blut: 'Todesstoß' verringert die Abklingzeit von 'Vampirblut' um 1 Sek.\n(2) Set Frost: Aktivierung von 'Säule des Frosts' erzeugt 30 Runenmacht.\n(2) Set Unheilig: Euer Diener verursacht 120% mehr Schaden, während 'Dunkle Transformation' aktiv ist.\n(4) Set Blut: Während 'Vampirblut' aktiv ist, kann Euer Blutschild nicht auf weniger als 3% Euer maximalen Gesundheit reduziert werden.\n(4) Set Frost: Während 'Säule des Frosts' aktiv ist, schließen Eure Spezialangriffe eine Seele in Eure Runenwaffe ein. Wenn 'Säule des Frosts' ausläuft, entlädt Eure Runenwaffe die Seelen auf Euer aktuelles Ziel und verursacht (3.51% der Angriffskraft)% Schaden pro Seele.\n(4) Set Unheilig: Wenn Ihr 'Dunkle Transformation' aktiviert, werden 1 Eurer Runen automatisch erneuert.\nVerkaufspreis:" }
entries[115538] = { ["name"] = "Ogerschädelverstärkte Stulpen", ["text"] = "Wird beim Aufheben gebunden\nHände Platte\n9 Rüstung\n+3 [Stärke oder Intelligenz]\n+5 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Tempowertung um + 3.\nHaltbarkeit 55 / 55\nKlassen: Todesritter\nOgerschädelverstärkte Schlachtrüstung (0/5)\nOgerschädelverstärkte Schienbeinschützer\nOgerschädelverstärkte Schulterstücke\nOgerschädelverstärkte Brustplatte\nOgerschädelverstärkte Stulpen\nOgerschädelverstärkter Großhelm\nAltes Set: Bonus ist nicht aktiv\n(2) Set Blut: 'Todesstoß' verringert die Abklingzeit von 'Vampirblut' um 1 Sek.\n(2) Set Frost: Aktivierung von 'Säule des Frosts' erzeugt 30 Runenmacht.\n(2) Set Unheilig: Euer Diener verursacht 120% mehr Schaden, während 'Dunkle Transformation' aktiv ist.\n(4) Set Blut: Während 'Vampirblut' aktiv ist, kann Euer Blutschild nicht auf weniger als 3% Euer maximalen Gesundheit reduziert werden.\n(4) Set Frost: Während 'Säule des Frosts' aktiv ist, schließen Eure Spezialangriffe eine Seele in Eure Runenwaffe ein. Wenn 'Säule des Frosts' ausläuft, entlädt Eure Runenwaffe die Seelen auf Euer aktuelles Ziel und verursacht (3.51% der Angriffskraft)% Schaden pro Seele.\n(4) Set Unheilig: Wenn Ihr 'Dunkle Transformation' aktiviert, werden 1 Eurer Runen automatisch erneuert.\nVerkaufspreis:" }
entries[115539] = { ["name"] = "Ogerschädelverstärkter Großhelm", ["text"] = "Wird beim Aufheben gebunden\nKopf Platte\n13 Rüstung\n+5 [Stärke oder Intelligenz]\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 5.\nErhöht Eure Tempowertung um + 4.\nHaltbarkeit 100 / 100\nKlassen: Todesritter\nOgerschädelverstärkte Schlachtrüstung (0/5)\nOgerschädelverstärkte Schienbeinschützer\nOgerschädelverstärkte Schulterstücke\nOgerschädelverstärkte Brustplatte\nOgerschädelverstärkte Stulpen\nOgerschädelverstärkter Großhelm\nAltes Set: Bonus ist nicht aktiv\n(2) Set Blut: 'Todesstoß' verringert die Abklingzeit von 'Vampirblut' um 1 Sek.\n(2) Set Frost: Aktivierung von 'Säule des Frosts' erzeugt 30 Runenmacht.\n(2) Set Unheilig: Euer Diener verursacht 120% mehr Schaden, während 'Dunkle Transformation' aktiv ist.\n(4) Set Blut: Während 'Vampirblut' aktiv ist, kann Euer Blutschild nicht auf weniger als 3% Euer maximalen Gesundheit reduziert werden.\n(4) Set Frost: Während 'Säule des Frosts' aktiv ist, schließen Eure Spezialangriffe eine Seele in Eure Runenwaffe ein. Wenn 'Säule des Frosts' ausläuft, entlädt Eure Runenwaffe die Seelen auf Euer aktuelles Ziel und verursacht (3.51% der Angriffskraft)% Schaden pro Seele.\n(4) Set Unheilig: Wenn Ihr 'Dunkle Transformation' aktiviert, werden 1 Eurer Runen automatisch erneuert.\nVerkaufspreis:" }
entries[115540] = { ["name"] = "Gewandung des lebendigen Holzes", ["text"] = "Wird beim Aufheben gebunden\nBrust Leder\n8 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 5.\nErhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 165 / 165\nKlassen: Druide\nSchlachtrüstung des lebendigen Holzes (0/5)\nGewandung des lebendigen Holzes\nHandschutz des lebendigen Holzes\nKopfstück des lebendigen Holzes\nBeinschützer des lebendigen Holzes\nSchiftung des lebendigen Holzes\nAltes Set: Bonus ist nicht aktiv\n(2) Set Gleichgewicht: Verringert die Zauberzeit von 'Solarzorn' und 'Lunarschlag' um 12%.\n(2) Set Wildheit: Wenn Ihr Blutungsschaden verursacht, erzeugt Ihr 1 Energie.\n(2) Set Wächter: Verringert die Kosten von 'Zermalmen' um 20%.\n(2) Set Wiederherstellung: 'Rasche Heilung' hat 1 zusätzliche Aufladung.\n(4) Set Gleichgewicht: Das Wirken von 'Solarzorn' und 'Lunarschlag' verringert die Abklingzeit von 'Himmlische Ausrichtung' um 3 Sek.\n(4) Set Wildheit: Während 'Berserker' aktiv ist, fügen Spezialangriffe dem Ziel im Verlauf von 6 Sek. zusätzlich 30% Blutungsschaden zu.\n(4) Set Wächter: Wenn Ihr ein Ziel mit 'Hauen' belegt, wird die Heilung Eures nächsten Einsatzes von 'Rasende Regeneration' um 10% erhöht. Bis zu 3-mal stapelbar.\n(4) Set Wiederherstellung: Wenn Ihr 2-mal hintereinander 'Heilende Berührung' wirkt, werden die Manakosten Eures nächsten Einsatzes von 'Wildwuchs' um 25% verringert.\nVerkaufspreis:" }
entries[115541] = { ["name"] = "Handschutz des lebendigen Holzes", ["text"] = "Wird beim Aufheben gebunden\nHände Leder\n4 Rüstung\n+3 [Beweglichkeit oder Intelligenz]\n+5 Ausdauer\nErhöht Eure Tempowertung um + 3.\nErhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 55 / 55\nKlassen: Druide\nSchlachtrüstung des lebendigen Holzes (0/5)\nGewandung des lebendigen Holzes\nHandschutz des lebendigen Holzes\nKopfstück des lebendigen Holzes\nBeinschützer des lebendigen Holzes\nSchiftung des lebendigen Holzes\nAltes Set: Bonus ist nicht aktiv\n(2) Set Gleichgewicht: Verringert die Zauberzeit von 'Solarzorn' und 'Lunarschlag' um 12%.\n(2) Set Wildheit: Wenn Ihr Blutungsschaden verursacht, erzeugt Ihr 1 Energie.\n(2) Set Wächter: Verringert die Kosten von 'Zermalmen' um 20%.\n(2) Set Wiederherstellung: 'Rasche Heilung' hat 1 zusätzliche Aufladung.\n(4) Set Gleichgewicht: Das Wirken von 'Solarzorn' und 'Lunarschlag' verringert die Abklingzeit von 'Himmlische Ausrichtung' um 3 Sek.\n(4) Set Wildheit: Während 'Berserker' aktiv ist, fügen Spezialangriffe dem Ziel im Verlauf von 6 Sek. zusätzlich 30% Blutungsschaden zu.\n(4) Set Wächter: Wenn Ihr ein Ziel mit 'Hauen' belegt, wird die Heilung Eures nächsten Einsatzes von 'Rasende Regeneration' um 10% erhöht. Bis zu 3-mal stapelbar.\n(4) Set Wiederherstellung: Wenn Ihr 2-mal hintereinander 'Heilende Berührung' wirkt, werden die Manakosten Eures nächsten Einsatzes von 'Wildwuchs' um 25% verringert.\nVerkaufspreis:" }
